<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,ApiError} from '../api/http'
type Case={id:string;name:string;question:string;source_type:'MYSQL'|'ELASTICSEARCH';expected_terms_json:string;enabled:boolean}
type Run={id:string;case_id:string;name:string;status:string;score?:number;matched_terms_json?:string;created_at:string}
type Option={id:string;name:string;type?:string}
const cases=ref<Case[]>([]),runs=ref<Run[]>([]),summary=ref<any>(),options=ref<{models:Option[];sources:Option[]}>({models:[],sources:[]}),dialog=ref(false),runDialog=ref(false),saving=ref(false),activeCase=ref<Case>()
const form=reactive({name:'',question:'',sourceType:'MYSQL',expectedTerms:''});const runForm=reactive({modelId:'',sourceId:''})
const availableSources=computed(()=>options.value.sources.filter(x=>x.type===activeCase.value?.source_type))
function terms(row:Case){try{return(JSON.parse(row.expected_terms_json) as string[]).join('、')}catch{return row.expected_terms_json}}
async function load(){[cases.value,runs.value,summary.value,options.value]=await Promise.all([api<Case[]>('/api/v1/admin/evaluations/cases'),api<Run[]>('/api/v1/admin/evaluations/runs'),api<any>('/api/v1/admin/evaluations/summary'),api<{models:Option[];sources:Option[]}>('/api/v1/chat/options')])}
async function create(){saving.value=true;try{await api('/api/v1/admin/evaluations/cases',{method:'POST',body:JSON.stringify({name:form.name,question:form.question,sourceType:form.sourceType,expectedTerms:form.expectedTerms.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean)})});dialog.value=false;Object.assign(form,{name:'',question:'',sourceType:'MYSQL',expectedTerms:''});await load();ElMessage.success('评测用例已创建')}catch(e){ElMessage.error(e instanceof ApiError?e.message:'创建失败')}finally{saving.value=false}}
async function toggle(row:Case){await api(`/api/v1/admin/evaluations/cases/${row.id}`,{method:'PATCH',body:JSON.stringify({enabled:!row.enabled})});await load()}
async function remove(row:Case){try{await ElMessageBox.confirm(`删除尚未运行的评测用例“${row.name}”？已有运行记录的用例请改为停用。`,'删除用例',{type:'warning'});await api(`/api/v1/admin/evaluations/cases/${row.id}`,{method:'DELETE'});await load()}catch(e){if(e instanceof ApiError)ElMessage.error(e.message)}}
function openRun(row:Case){activeCase.value=row;runForm.modelId=options.value.models[0]?.id??'';runForm.sourceId=options.value.sources.find(x=>x.type===row.source_type)?.id??'';runDialog.value=true}
async function run(){if(!activeCase.value)return;saving.value=true;try{await api(`/api/v1/admin/evaluations/cases/${activeCase.value.id}/runs`,{method:'POST',body:JSON.stringify(runForm)});runDialog.value=false;ElMessage.success('评测任务已提交');setTimeout(load,1500)}catch(e){ElMessage.error(e instanceof ApiError?e.message:'提交失败')}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="quality"><div class="toolbar"><div><h2>问答质量</h2><p>维护固定问题集，复用真实问答链路自动执行并统计关键词命中率</p></div><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="dialog=true">新建评测用例</el-button></div></div><div class="cards"><el-card shadow="never"><span>用户反馈</span><strong>{{summary?.feedback?.total??0}}</strong><small>有帮助 {{summary?.feedback?.helpful??0}} · 需改进 {{summary?.feedback?.unhelpful??0}}</small></el-card><el-card shadow="never"><span>已完成评测</span><strong>{{summary?.evaluations?.total??0}}</strong><small>平均命中率 {{Math.round((summary?.evaluations?.average_score??0)*100)}}%</small></el-card></div><el-card shadow="never"><template #header><b>固定评测集</b></template><el-table :data="cases"><el-table-column prop="name" label="名称" width="180"/><el-table-column prop="source_type" label="类型" width="130"/><el-table-column prop="question" label="问题" min-width="260" show-overflow-tooltip/><el-table-column label="预期关键词" min-width="220"><template #default="s">{{terms(s.row)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="200"><template #default="s"><el-button link type="primary" :disabled="!s.row.enabled" @click="openRun(s.row)">运行</el-button><el-button link @click="toggle(s.row)">{{s.row.enabled?'停用':'启用'}}</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-card><el-card shadow="never"><template #header><b>最近评测</b></template><el-table :data="runs" max-height="360"><el-table-column prop="created_at" label="提交时间" width="180"><template #default="s">{{new Date(s.row.created_at).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column prop="name" label="用例" min-width="180"/><el-table-column prop="status" label="状态" width="120"/><el-table-column label="命中率" width="120"><template #default="s">{{s.row.score==null?'—':`${Math.round(s.row.score*100)}%`}}</template></el-table-column><el-table-column prop="matched_terms_json" label="已命中关键词" min-width="260" show-overflow-tooltip/></el-table></el-card><el-dialog v-model="dialog" title="新建评测用例" width="560px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="数据源类型"><el-radio-group v-model="form.sourceType"><el-radio value="MYSQL">MySQL</el-radio><el-radio value="ELASTICSEARCH">Elasticsearch</el-radio></el-radio-group></el-form-item><el-form-item label="测试问题"><el-input v-model="form.question" type="textarea" :rows="3"/></el-form-item><el-form-item label="预期关键词"><el-input v-model="form.expectedTerms" type="textarea" :rows="2" placeholder="用逗号或换行分隔；在查询或答案中命中即计分"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></template></el-dialog><el-dialog v-model="runDialog" title="运行评测" width="480px"><el-form label-position="top"><el-form-item label="模型"><el-select v-model="runForm.modelId" style="width:100%"><el-option v-for="x in options.models" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="数据源"><el-select v-model="runForm.sourceId" style="width:100%"><el-option v-for="x in availableSources" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="runDialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!runForm.modelId||!runForm.sourceId" @click="run">提交评测</el-button></template></el-dialog></div></template>
<style scoped>.quality{display:flex;flex-direction:column;gap:16px}.toolbar{display:flex;justify-content:space-between;align-items:center}.toolbar h2{margin:0 0 6px}.toolbar p{margin:0;color:#7b8496}.cards{display:grid;grid-template-columns:repeat(2,minmax(240px,1fr));gap:14px}.cards span,.cards small{display:block;color:#7b8496}.cards strong{display:block;font-size:28px;margin:10px 0;color:#17233c}</style>
